const cveId = $('When Executed by Another Workflow').first().json.cveId.trim().toUpperCase();
const res = $input.first().json;

// 404 means OSV has no record. Any other non-200 status is a real failure and should stop the workflow.
if (res.statusCode === 404) {
  return [{ json: { cveId, found: false, message: 'OSV has no record for this CVE.' } }];
}
if (res.statusCode !== 200) {
  throw new Error(`OSV returned HTTP ${res.statusCode} for ${cveId}`);
}

// Package names and fixed versions live on ecosystem advisories (GHSA, PYSEC, GO, RUSTSEC...),
// not on the CVE record itself
const aliases = (res.body.aliases ?? []).filter(id => !id.startsWith('CVE-')).slice(0, 4);

if (aliases.length === 0) {
  return [{
    json: {
      cveId,
      found: true,
      packageCount: 0,
      affectedPackages: [],
      message: 'OSV has this CVE but no linked package advisory. It probably affects software outside package registries, such as appliances or operating system components.',
    },
  }];
}

return aliases.map(aliasId => ({ json: { cveId, aliasId } }));

const cveId = $('When Executed by Another Workflow').first().json.cveId.trim().toUpperCase();
const packages = new Map();

for (const item of $input.all()) {
  const advisory = item.json;
  for (const affected of advisory.affected ?? []) {
    if (!affected.package?.name) continue;

    const key = `${affected.package.ecosystem}:${affected.package.name}`;
    const entry = packages.get(key) ?? {
      ecosystem: affected.package.ecosystem,
      package: affected.package.name,
      fixedVersions: new Set(),
      advisories: new Set(),
    };

    (affected.ranges ?? [])
      .flatMap(r => r.events ?? [])
      .map(e => e.fixed)
      .filter(Boolean)
      .forEach(v => entry.fixedVersions.add(v));
    entry.advisories.add(advisory.id);
    packages.set(key, entry);
  }
}

const list = [...packages.values()].map(p => ({
  ecosystem: p.ecosystem,
  package: p.package,
  fixedVersions: [...p.fixedVersions],
  advisories: [...p.advisories],
}));

return [{
  json: {
    cveId,
    found: true,
    packageCount: list.length,
    affectedPackages: list.slice(0, 10),
    fixAvailable: list.some(p => p.fixedVersions.length > 0),
  },
}];
